,"},{"scene":"S04","startFrame":1760,"endFrame":1850,"text":"pilih printer yang mau kita sharing, lalu buka Printer Properties."},{"scene":"S04","startFrame":1850,"endFrame":1940,"text":"Masuk ke tab Sharing,"},{"scene":"S04","startFrame":1940,"endFrame":2060,"text":"centang Share this printer,"},{"scene":"S04","startFrame":2060,"endFrame":2150,"text":"lalu klik OK."},{"scene":"S05","startFrame":2150,"endFrame":2234,"text":"Sekarang, kita pindah ke komputer kedua."},{"scene":"S05","startFrame":2234,"endFrame":2282,"text":"Tekan Windows plus R,"},{"scene":"S05","startFrame":2282,"endFrame":2390,"text":"lalu masukkan alamat IP komputer pertama."},{"scene":"S05","startFrame":2390,"endFrame":2438,"text":"Kalau printernya udah muncul,"},{"scene":"S05","startFrame":2438,"endFrame":2600,"text":"tinggal klik kanan dan pilih Connect."},{"scene":"S06","startFrame":2600,"endFrame":2720,"text":"Nah, sekarang kita udah bisa nge-print"},{"scene":"S06","startFrame":2720,"endFrame":2870,"text":"dari kedua komputer tanpa perlu Wi-Fi."},{"scene":"S06","startFrame":2870,"endFrame":2945,"text":"Tapi pastikan komputer yang terhubung langsung ke printer"},{"scene":"S06","startFrame":2945,"endFrame":2990,"text":"tetap menyala, ya."},{"scene":"S07","startFrame":2990,"endFrame":3052,"text":"Kalau kamu punya pengalaman"},{"scene":"S07","startFrame":3052,"endFrame":3109,"text":"soal sharing printer,"},{"scene":"S07","startFrame":3109,"endFrame":3215,"text":"coba tulis di kolom komentar."},{"scene":"S08","startFrame":3215,"endFrame":3395,"text":""}]}}} /></Folder>
